function boblift_brand_wordmark_svg(string $class = '', string $label = 'BOB-LIFT'): string
{
    static $count = 0;
    $count++;
    $outline = boblift_brand_wordmark_outline();
    $clip = 'boblift-wordmark-clip-' . $count;
    return '<svg class="' . esc_attr($class) . '" viewBox="' . $outline['viewBox'] . '" role="img" aria-label="' . esc_attr($label) . '">'
        . '<defs><clipPath id="' . $clip . '"><path transform="' . $outline['transform'] . '" d="' . $outline['d'] . '"/></clipPath></defs>'
        . '<g clip-path="url(#' . $clip . ')">'
        . '<rect width="3493" height="1180" fill="#11609B"/>'
        . '<path d="M0 733 Q1746 560 3493 728 V1180 H0 Z" fill="#2B4E72"/>'
        . '</g></svg>';
}

/** The outline as a data URI, for CSS masks (the photo-filled layer of the About hero). */
function boblift_brand_wordmark_mask_uri(): string
{
    $outline = boblift_brand_wordmark_outline();
    $svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="' . $outline['viewBox'] . '"><path transform="' . $outline['transform'] . '" d="' . $outline['d'] . '"/></svg>';
    return 'data:image/svg+xml,' . rawurlencode($svg);
}
